+// CUDA graphs keep the execution plans and host data they were recorded from alive, and the
+// frontend releases them again once those graphs are gone.
+
+#include <algorithm>
+#include <chrono>
+#include <cstdint>
+#include <memory>
+#include <sstream>
+#include <thread>
+#include <type_traits>
+#include <unordered_map>
+#include <vector>
