+    int64_t const b = 2, h = 8, s = 128, d = 64;
+    Surface<half> q_gpu(b * h * s * d);
+    Surface<half> k_gpu(b * h * s * d);
+    Surface<half> v_gpu(b * h * s * d);
+    Surface<half> o_gpu(b * h * s * d);
